  'nik-decoder': {
    title: 'Free NIK / KTP Decoder — Validate & Read an Indonesian ID Number',
    description: 'Validate an Indonesian NIK (16-digit KTP number) and decode the province, birth date, gender and serial. Runs in your browser — the NIK is never uploaded.',
    intro: 'This free NIK decoder checks the structure of an Indonesian NIK (the 16-digit number on a KTP) and breaks it down: province, regency and district codes, birth date, gender (via the day+40 rule) and the registration serial. Because a NIK is personal data, everything is decoded locally in your browser and nothing is ever uploaded.',
    howTo: [
      'Type or paste the 16-digit NIK.',
      'See whether the structure is valid, and read the province, birth date and gender.',
      'Check the age, computed from the decoded birth date.',
      'Copy the breakdown if you need it.',
    ],
    faqs: [
      { q: 'Is my NIK uploaded anywhere?', a: 'No. A NIK is sensitive personal data, so this tool decodes it entirely in your browser — it is never sent to a server.' },
      { q: 'How is gender encoded in a NIK?', a: 'The birth day is stored in positions 7–8. For women, 40 is added to the day, so a value of 41–71 means female and the real day is that number minus 40.' },
      { q: 'Can it show the full district name?', a: 'It decodes the province name and shows the regency and district code numbers. Mapping those codes to full names needs the official Kemendagri region dataset, which is out of scope here.' },
      { q: 'Does a valid structure mean the NIK is real?', a: 'No. A NIK has no checksum, so this tool can confirm the format is plausible (valid province, date and length) but cannot verify that a NIK is officially registered.' },
      { q: 'Which year does a 2-digit birth year mean?', a: 'The NIK stores only two year digits, so the tool infers the century: if the 2000s reading would be in the future it uses the 1900s instead.' },
    ],
  },
