export const toolSeo: Record<Lang, Record<string, ToolSeoContent>> = { en, id };

export function getToolSeo(toolId: string, lang: Lang = 'en'): ToolSeoContent | undefined {
  return toolSeo[lang]?.[toolId] ?? toolSeo.en[toolId];
}
